import { callableConceptMember, CONCEPT_MEMBER_ROLES, conceptMetadataOf, } from "../reactions/concepts/concept-metadata.js";
function staticQueryPromisesOf(concept) {
    return Object.getPrototypeOf(concept)?.constructor
        ?.queries;
}
